# Lunar Konstruksi - Fase 7.2 Construction Reference Direction
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Write-Phase([string]$Message) { Write-Host "[FASE 7.2] $Message" -ForegroundColor Cyan }
function Fail-Phase([string]$Message) { Write-Host ""; Write-Host "[FASE 7.2] GAGAL: $Message" -ForegroundColor Red; exit 1 }
function Write-Utf8NoBom([string]$Path, [string]$Content) {
  $parent = Split-Path -Parent $Path
  if ($parent -and -not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }
  $encoding = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $encoding)
}
function Decode([string]$Value) { return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Value)) }

$repoRoot = (& git rev-parse --show-toplevel 2>$null)
if (-not $repoRoot) { Fail-Phase "Jalankan script dari root repository Lunar Konstruksi." }
$repoRoot = $repoRoot.Trim()
Set-Location $repoRoot
$trackedStatus = & git status --porcelain --untracked-files=no
if ($LASTEXITCODE -ne 0) { Fail-Phase "Tidak bisa membaca git status." }
if ($trackedStatus) { Write-Host $trackedStatus; Fail-Phase "Ada perubahan tracked yang belum disimpan. Commit/stash dulu." }

$required = @(
  "package.json",
  "components/site/redesign/public-helpers.ts",
  "components/site/redesign/public-page-renderer.tsx",
  "components/site/redesign/public-header.tsx",
  "components/site/redesign/public-footer.tsx",
  "features/public-site/server.ts",
  "features/site-settings/server.ts",
  "features/navigation/server.ts",
  "app/api/public/leads/route.ts"
)
$missing = @($required | Where-Object { -not (Test-Path -LiteralPath $_) })
if ($missing.Count -gt 0) { Write-Host "[FASE 7.2] Prasyarat yang belum ada:" -ForegroundColor Yellow; $missing | ForEach-Object { Write-Host "  - $_" }; Fail-Phase "Pastikan Fase 1-7.1 sudah terpasang." }

Write-Phase "Mengganti bahasa visual ke construction-first reference direction..."
$payload = @{}
$payload["PHASE7_2_CONSTRUCTION_DIRECTION.md"] = ""
$payload["components/site/redesign/public-contact-form.tsx"] = ""
$payload["components/site/redesign/public-footer.tsx"] = ""
$payload["components/site/redesign/public-header.tsx"] = ""
$payload["components/site/redesign/public-page-renderer.tsx"] = ""

foreach ($entry in $payload.GetEnumerator()) {
  $target = Join-Path $repoRoot $entry.Key
  Write-Utf8NoBom $target (Decode $entry.Value)
  Write-Host "[FASE 7.2] write  $($entry.Key)" -ForegroundColor DarkGray
}

Write-Host ""
Write-Host "[FASE 7.2] Construction reference redesign selesai." -ForegroundColor Green
Write-Host "[FASE 7.2] Tidak ada dependency baru; npm install tidak diperlukan." -ForegroundColor Green
Write-Host ""
Write-Host "Validasi:" -ForegroundColor Cyan
Write-Host "  npm run lint"
Write-Host "  npm run typecheck"
Write-Host "  npm run build"
Write-Host "  git diff --check"
